all_original_proposals.original_declaration:
abstract thing CellularBody
    "An identified material body described at the structural scale of a biological cell."
    is physical:MaterialBody;

abstract thing TissueBody
    "An identified biological material body organized as a tissue."
    is physical:MaterialBody;

abstract thing OrganBody
    "An identified biological material body organized as an organ."
    is physical:MaterialBody;

structural directed relationship BiologicalParentOf
    "An identified organism is a biological progenitor of another identified organism."
    links life:Individual to life:Individual;

all_original_proposals.integrated_declaration:
structural directed relationship BiologicalParentOf
    "An identified organism is a biological progenitor of another identified organism."
    links life:Individual to life:Individual;
